using System;using System.Drawing;using System.Windows.Forms;using GymAndFitnessManagementSystem.Common;using GymAndFitnessManagementSystem.Data;
namespace GymAndFitnessManagementSystem.Forms{public class SignUpForm:Form{TextBox n=new TextBox(),e=new TextBox(),p=new TextBox(),ph=new TextBox(),a=new TextBox();Label msg=new Label();public SignUpForm(){Theme.Apply(this,"Customer Sign Up");Size=new Size(650,630);Controls.Add(Theme.Header("Customer Sign Up"));var panel=new Panel{Dock=DockStyle.Fill,Padding=new Padding(110,30,110,30),AutoScroll=true};Controls.Add(panel);string[] labs={"Full Name","Email","Password (min 6 characters)","Phone","Address"};TextBox[] xs={n,e,p,ph,a};int y=25;for(int i=0;i<xs.Length;i++){panel.Controls.Add(new Label{Text=labs[i],Left=110,Top=y,Width=360});y+=24;xs[i].SetBounds(110,y,360,30);panel.Controls.Add(xs[i]);y+=48;}p.UseSystemPasswordChar=true;msg.SetBounds(110,y,360,45);msg.ForeColor=Theme.Danger;panel.Controls.Add(msg);y+=50;var b=Theme.Button("Create Account",Save);b.SetBounds(110,y,170,42);panel.Controls.Add(b);var c=Theme.Button("Back",(o,z)=>Close());c.SetBounds(300,y,170,42);panel.Controls.Add(c);}void Save(object o,EventArgs z){try{if(string.IsNullOrWhiteSpace(n.Text)||string.IsNullOrWhiteSpace(e.Text)||!e.Text.Contains("@")||p.Text.Length<6){msg.Text="Enter a valid name, email and a password of at least 6 characters.";return;}Repositories.RegisterCustomer(n.Text.Trim(),e.Text.Trim(),p.Text,ph.Text.Trim(),a.Text.Trim());MessageBox.Show("Account created successfully.");Close();}catch(Exception ex){msg.Text=ex.Message;}}}}
